import React, { useState, useEffect } from 'react';
import api from './api';
import { useLiquidGlass } from './hooks/useLiquidGlass';
import AuthModal from './components/AuthModal';
import InteractiveSeating from './components/InteractiveSeating';
import GateSimulator from './components/GateSimulator';
import OrganizerStudio from './components/OrganizerStudio';
import AdminFleetMonitor from './components/AdminFleetMonitor';

function App() {
    const [user, setUser] = useState(() => {
        const saved = localStorage.getItem('tf_user');
        return saved ? JSON.parse(saved) : null;
    });
    const [activeTab, setActiveTab] = useState('catalog');
    const [events, setEvents] = useState([]);
    const [selectedEvent, setSelectedEvent] = useState(null);
    const [tickets, setTickets] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('All');
    const [toasts, setToasts] = useState([]);

    const { rootRef: navRootRef } = useLiquidGlass([user?.id, activeTab, tickets.length], {
        cornerRadius: 999,
        refraction: 0.78,
        blurAmount: 0.25,
    });

    const { rootRef: heroRootRef } = useLiquidGlass([user?.id, activeTab, selectedEvent?.id], {
        cornerRadius: 32,
        refraction: 0.75,
        blurAmount: 0.22,
    });

    const showToast = (message, type = 'info') => {
        const id = Date.now();
        setToasts(prev => [...prev, { id, message, type }]);
        setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3500);
    };

    const fetchEvents = async () => {
        try {
            const res = await api.get('/events');
            setEvents(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    const fetchTickets = async () => {
        if (!user) return;
        try {
            const res = await api.get('/tickets/my');
            setTickets(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        if (user) {
            fetchEvents();
            fetchTickets();
        }
    }, [user]);

    const handleLogout = () => {
        localStorage.removeItem('tf_token');
        localStorage.removeItem('tf_user');
        setUser(null);
        setSelectedEvent(null);
        setActiveTab('catalog');
    };

    if (!user) {
        return (
            <>
                <AuthModal onAuthSuccess={(u) => setUser(u)} showToast={showToast} />
                <ToastContainer toasts={toasts} />
            </>
        );
    }

    const filteredEvents = events.filter(ev => {
        const matchesCat = selectedCategory === 'All' || ev.category === selectedCategory;
        const matchesQuery =
            ev.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            ev.venue.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesCat && matchesQuery;
    });

    return (
        <div className="min-h-screen flex flex-col relative">
            {/* Fixed Ambient Spatial Canvas */}
            <div className="fixed inset-0 pointer-events-none z-0 lg-backdrop-mesh" />

            {/* Floating WebGL Liquid Glass Dock */}
            <header className="sticky top-4 z-40 px-4 sm:px-6 lg:px-8">
                <div ref={navRootRef} className="max-w-6xl mx-auto relative">
                    <div className="lg-backdrop-mesh rounded-full opacity-60" />
                    <div className="lg-surface rounded-full px-5 py-2.5 flex flex-wrap items-center justify-between gap-3">
                        <button
                            onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                            className="flex items-center gap-2.5 text-left"
                        >
                            <span className="text-lg">🎟️</span>
                            <span className="font-bold text-base tracking-tight text-white">TicketFlow</span>
                        </button>

                        <nav className="flex items-center gap-1 clean-well p-1 rounded-full">
                            <button
                                onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                                className={`px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                    activeTab === 'catalog' ? 'bg-white text-slate-950' : 'text-white/70 hover:text-white'
                                }`}
                            >
                                Explore
                            </button>
                            <button
                                onClick={() => setActiveTab('tickets')}
                                className={`flex items-center gap-1.5 px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                    activeTab === 'tickets' ? 'bg-white text-slate-950' : 'text-white/70 hover:text-white'
                                }`}
                            >
                                <span>Wallet</span>
                                <span className={`text-[10px] font-mono px-1.5 rounded-full ${
                                    activeTab === 'tickets' ? 'bg-slate-950/15 text-slate-950' : 'bg-white/15 text-white'
                                }`}>
                  {tickets.length}
                </span>
                            </button>
                            {(user.role === 'ORGANIZER' || user.role === 'ADMIN') && (
                                <button
                                    onClick={() => setActiveTab('organizer')}
                                    className={`px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                        activeTab === 'organizer' ? 'bg-white text-slate-950' : 'text-white/70 hover:text-white'
                                    }`}
                                >
                                    Studio
                                </button>
                            )}
                            {user.role === 'ADMIN' && (
                                <button
                                    onClick={() => setActiveTab('admin')}
                                    className={`px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                        activeTab === 'admin' ? 'bg-white text-slate-950' : 'text-white/70 hover:text-white'
                                    }`}
                                >
                                    Fleet
                                </button>
                            )}
                        </nav>

                        <div className="flex items-center gap-3">
                            <span className="hidden md:inline text-xs text-white/70 font-medium">{user.fullName}</span>
                            <button
                                onClick={handleLogout}
                                className="px-3.5 py-1.5 rounded-full bg-white/10 hover:bg-white/20 text-xs font-medium text-white transition"
                            >
                                Sign Out
                            </button>
                        </div>
                    </div>
                </div>
            </header>

            <ToastContainer toasts={toasts} />

            <main className="relative z-10 flex-1 max-w-6xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {activeTab === 'catalog' && !selectedEvent && (
                    <div className="space-y-8">
                        {/* WebGL Liquid Glass Hero */}
                        <div ref={heroRootRef} className="relative">
                            <div className="lg-backdrop-mesh rounded-[32px] opacity-80" />
                            <div className="lg-surface rounded-[32px] p-8 sm:p-10 flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                                <div className="max-w-xl space-y-2">
                                    <p className="text-xs font-mono uppercase tracking-widest text-sky-300">Spatial Ticketing</p>
                                    <h1 className="text-3xl sm:text-4xl font-bold tracking-tight text-white">
                                        Live Events. Seamless Entry.
                                    </h1>
                                    <p className="text-sm text-white/65 leading-relaxed">
                                        Select exact seats, store cryptographic passes in your Wallet, and walk straight through optical gates.
                                    </p>
                                </div>

                                <div className="w-full lg:w-80 space-y-3">
                                    <input
                                        type="text"
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        placeholder="Search events or venues..."
                                        className="w-full px-4 py-2.5 rounded-full clean-well text-sm text-white placeholder-white/40 focus:outline-none focus:border-white/40"
                                    />
                                    <div className="flex flex-wrap gap-1.5">
                                        {['All', 'Concerts', 'Festivals', 'Theater', 'Comedy'].map(cat => (
                                            <button
                                                key={cat}
                                                onClick={() => setSelectedCategory(cat)}
                                                className={`px-3 py-1 rounded-full text-xs font-medium transition ${
                                                    selectedCategory === cat ? 'bg-white text-slate-950' : 'bg-white/10 text-white/75 hover:bg-white/20'
                                                }`}
                                            >
                                                {cat}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Minimalist Event Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {filteredEvents.map(ev => (
                                <div key={ev.id} className="clean-glass-card rounded-[28px] p-7 flex flex-col justify-between gap-6">
                                    <div className="space-y-3">
                                        <div className="flex items-center justify-between text-xs">
                                            <span className="px-3 py-1 rounded-full bg-white/10 text-white/90 font-medium">{ev.category}</span>
                                            <span className="font-mono text-emerald-300">{ev.totalCapacity - ev.soldCount} seats left</span>
                                        </div>
                                        <h3 className="text-xl font-bold tracking-tight text-white">{ev.title}</h3>
                                        <div className="text-xs text-white/60 space-y-0.5">
                                            <p>{ev.venue}</p>
                                            <p className="font-mono text-white/45">{ev.date}</p>
                                        </div>
                                    </div>

                                    <div className="pt-4 border-t border-white/10 flex items-center justify-between">
                                        <div>
                                            <p className="text-[11px] text-white/45">From</p>
                                            <p className="text-lg font-bold font-mono text-white">{ev.gaPrice} RON</p>
                                        </div>
                                        <button onClick={() => setSelectedEvent(ev)} className="px-5 py-2.5 rounded-full apple-pill font-bold text-xs">
                                            Select Seats
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {activeTab === 'catalog' && selectedEvent && (
                    <InteractiveSeating
                        event={selectedEvent}
                        user={user}
                        onBack={() => { setSelectedEvent(null); fetchEvents(); }}
                        onCheckoutSuccess={() => {
                            setSelectedEvent(null);
                            fetchEvents();
                            fetchTickets();
                            setActiveTab('tickets');
                        }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'tickets' && (
                    <GateSimulator
                        tickets={tickets}
                        onRefreshTickets={fetchTickets}
                        onBuyMore={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'organizer' && (
                    <OrganizerStudio events={events} onEventCreated={fetchEvents} showToast={showToast} />
                )}

                {activeTab === 'admin' && (
                    <AdminFleetMonitor showToast={showToast} />
                )}
            </main>
        </div>
    );
}

const ToastContainer = ({ toasts }) => (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-2 max-w-xs w-full pointer-events-none px-4 sm:px-0">
        {toasts.map(t => (
            <div key={t.id} className="pointer-events-auto clean-glass-card px-4 py-3 rounded-full text-xs font-medium text-white shadow-2xl flex items-center gap-2.5">
        <span className={`w-2 h-2 rounded-full shrink-0 ${
            t.type === 'success' ? 'bg-emerald-400' : t.type === 'error' ? 'bg-rose-400' : 'bg-sky-400'
        }`} />
                <p>{t.message}</p>
            </div>
        ))}
    </div>
);

export default App;
